// Render every .mmd in this directory to a light and a dark SVG.
//
// These SVGs used to be generated by nothing. The README captioned them
// "Source: <name>.mmd" with no script behind it and no check, so the obvious
// way to fix a wrong word in a picture was to edit the picture, and the .mmd
// quietly stopped being the source of anything. This script is what makes that
// caption true; check.mjs is what keeps it true.
//
//   node docs/diagrams/build.mjs          rebuild every diagram
//   node docs/diagrams/check.mjs          verify without rendering (no deps)
//
// Needs network on first run: it fetches @mermaid-js/mermaid-cli through npx,
// which brings its own Chromium. check.mjs deliberately needs neither.
import { readFile, writeFile, readdir, unlink } from 'node:fs/promises';
import { dirname, join, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const run = promisify(execFile);
const HERE = dirname(fileURLToPath(import.meta.url));
const THEME = JSON.parse(await readFile(join(HERE, 'theme.json'), 'utf8'));

// Mermaid's own variable names, fed from theme.json. theme: 'base' is the only
// built-in that honours themeVariables — 'default' and 'dark' ignore them and
// silently hand back the stock lavender-and-purple palette, which belongs to no
// part of this product.
const config = (t) => ({
  theme: 'base',
  themeVariables: {
    background: t.plate, primaryColor: t.node, primaryTextColor: t.text,
    primaryBorderColor: t.nodeBorder, secondaryColor: t.clusterBkg, tertiaryColor: t.clusterBkg,
    mainBkg: t.node, nodeBorder: t.nodeBorder, nodeTextColor: t.text, textColor: t.text,
    lineColor: t.line, edgeLabelBackground: t.plate, clusterBkg: t.clusterBkg,
    clusterBorder: t.clusterBorder, titleColor: t.text,
    fontFamily: 'ui-sans-serif, -apple-system, Segoe UI, Helvetica, Arial, sans-serif',
    fontSize: '15px',
  },
  // htmlLabels: false emits <text>/<tspan> rather than <foreignObject>. A
  // foreignObject is not rendered when an SVG is loaded through an <img>, which
  // is how GitHub serves README images and how every renderer outside a browser
  // treats them — HTML labels are a diagram that can come out silently empty.
  htmlLabels: false,
  flowchart: {
    curve: 'basis', nodeSpacing: 40, rankSpacing: 52, padding: 12,
    useMaxWidth: true, htmlLabels: false,
    // A README column is about 830px wide. Wrapping narrower makes nodes taller
    // and the graph less wide, so it is scaled down less and its labels stay
    // legible instead of shrinking to fit. Not lower than this: mermaid escapes
    // a second time when it wraps, and it wraps by character, so a narrower
    // setting splits "&lt;" across two tspans and the picture shows the raw
    // entity instead of the "<" in ISnapshotProvider&lt;T&gt;.
    wrappingWidth: 160,
  },
});

const sources = (await readdir(HERE)).filter((f) => f.endsWith('.mmd')).sort();
if (!sources.length) { console.error('no .mmd files beside this script'); process.exit(1); }

for (const file of sources) {
  for (const variant of ['light', 'dark']) {
    const t = THEME[variant];
    const cfg = join(HERE, `.mmdc-${variant}.json`);
    await writeFile(cfg, JSON.stringify(config(t), null, 2));
    const out = join(HERE, `${basename(file, '.mmd')}-${variant}.svg`);
    await run('npx', ['-y', '@mermaid-js/mermaid-cli', '-i', join(HERE, file), '-o', out,
                      '-c', cfg, '-b', t.plate, '--quiet'],
              { shell: true, maxBuffer: 64 * 1024 * 1024 });
    await unlink(cfg);
    const svg = await readFile(out, 'utf8');

    const vb = /viewBox="[^"]*?([\d.]+)\s+([\d.]+)"/.exec(svg);
    console.log(`  ${basename(out).padEnd(38)} ${vb ? Math.round(+vb[1]) + 'x' + Math.round(+vb[2]) : '?'}`);
  }
}
console.log(`\n${sources.length} diagram(s) rendered. Now run: node docs/diagrams/check.mjs`);
